import index from "../../content/projects/index.json";

/**
 * Project data for the site. Generated by `npm run sync` from the packages in
 * ../projects (see scripts/sync-projects.mjs); never edit index.json by hand.
 */
export type Localized = { ar: string; en: string };
type Sizes = Record<string, { avif: string; webp: string }>;
export type ImageSet = { width: number; height: number; sizes: Sizes };

export type Project = {
  slug: string;
  order: number;
  tier: "main" | "other";
  status: "live" | "delivered";
  statusNote: Localized | null;
  year: string;
  title: Localized;
  name: Localized;
  summary: Localized;
  card: {
    line: Localized;
    role: Localized;
    stats: { value: string; label: Localized }[];
  };
  related: { slug: string; relation: Localized }[];
  partOf: { slug: string; relation: Localized; tag: Localized } | null;
  links: { live: string | null; demo: string | null };
  media: {
    cover: ImageSet;
    og: string | null;
    loop: { mp4: string; webm: string; poster: ImageSet };
  };
};

export const projects = (index as Project[]).slice().sort((a, b) => a.order - b.order);
export const mainProjects = projects.filter((p) => p.tier === "main");
export const otherProjects = projects.filter((p) => p.tier === "other");
export const projectBySlug = (slug: string) => projects.find((p) => p.slug === slug);

/** srcset strings for an ImageSet. */
export function srcSets(img: ImageSet) {
  const entries = Object.entries(img.sizes).sort((a, b) => Number(a[0]) - Number(b[0]));
  return {
    avif: entries.map(([w, s]) => `${s.avif} ${w}w`).join(", "),
    webp: entries.map(([w, s]) => `${s.webp} ${w}w`).join(", "),
    fallback: entries[entries.length - 1][1].webp,
  };
}
